438: function buildObjectiveBeacon() {
439:   const g = new THREE.Group();
440:   const mat = new THREE.MeshBasicMaterial({ color:0xff4338, transparent:true, opacity:.5, depthWrite:false, blending:THREE.AdditiveBlending, side:THREE.DoubleSide });
441:   const ring = new THREE.Mesh(new THREE.RingGeometry(1.7,2.1,32), mat);
442:   ring.rotation.x = -Math.PI/2; ring.position.y = .1; g.add(ring);
443:   const beam = new THREE.Mesh(new THREE.CylinderGeometry(.06,.06,9,6), mat.clone());
444:   beam.position.y = 4.5; beam.material.opacity = .18; g.add(beam);
445:   const light = new THREE.PointLight(0xff4338, 5, 20, 2); light.position.y = 2; g.add(light);
446:   g.userData = { ring, beam, light };
447:   g.visible = false;
448:   scene.add(g);
449:   objectiveBeacon = g;
450: }
