452: function updateObjectiveBeacon(dt) {
453:   if (!objectiveBeacon) return;
454:   if (!objectiveTarget || gameMode === 'menu') { objectiveBeacon.visible = false; return; }
455:   objectiveBeacon.visible = true;
456:   objectiveBeacon.position.set(objectiveTarget.x, 0, objectiveTarget.z);
457:   const t = elapsed;
458:   objectiveBeacon.userData.ring.scale.setScalar(1 + Math.sin(t * 2.2) * .16);
459:   objectiveBeacon.userData.ring.material.opacity = .32 + Math.sin(t * 2.2) * .12;
460:   objectiveBeacon.userData.beam.material.opacity = .1 + Math.sin(t * 1.4) * .04;
461:   objectiveBeacon.userData.light.intensity = 3 + Math.sin(t * 2.2) * 1.5;
462: }
