876: function refreshDialogueChoices(npc) {
877:   if (!ui.dialogueOpen) return;
878:   const choices = choicesFor(npc);
879:   const box = $('dialogue-choices');
880:   box.innerHTML = '';
881:   for (const ch of choices) {
882:     const b = document.createElement('button');
883:     b.textContent = ch.label;
884:     if (ch.special) b.classList.add('special');
885:     b.addEventListener('click', () => dialogueChoice(npc, ch));
886:     box.appendChild(b);
887:   }
888: }
