import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:8123/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__BELLINGHAM, { timeout: 30000 });
await page.evaluate(() => window.__BELLINGHAM.startGame(false));
await page.waitForTimeout(2500);
const checks = await page.evaluate(() => {
  const game = window.__BELLINGHAM;
  const results = [];
  const cases = [
    ['salt_cedar', 'table'],
    ['north_sound', 'shower'],
    ['static_club', 'dance'],
  ];
  for (const [business, action] of cases) {
    game.state.player.money = 0;
    game.openBusiness(business);
    document.querySelector(`[data-arg="${action}"]`).click();
    results.push({ action, money: game.state.player.money, blocked: document.querySelector('#toasts')?.innerText.includes('NO CASH') });
    game.closePanel();
  }
  game.state.flags.artifacts = ['token'];
  game.state.relationships.wren = { affinity: 20 };
  game.openEndingChoices();
  results.push({ escapeReq: document.querySelector('#panel-body')?.innerText.includes('Brass Bus Token · Wren friendship'), noControlReq: !document.querySelector('#panel-body')?.innerText.includes('less than 50%') });
  game.closePanel();
  game.openPhone('status');
  return results;
});
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/current.jpg', type: 'jpeg', quality: 80 });
console.log(JSON.stringify({ checks, errors, screenshot: 'screenshots/current.jpg', dimensions: await page.evaluate(() => ({ w: innerWidth, h: innerHeight })) }, null, 2));
await browser.close();
